// 161 chars by @SnoopethDuckDuck thanks
void mainImage( out vec4 o, vec2 u)
{
    o.xyz = iResolution;    
    for(u = (u+u-o.xy)/o.y; o.z++<65.;)
        u = (abs(u)-.75) * mat2(.409,-1,1,.409) * 1.018;    
    o = vec4(u.x=dot(u,u), u.x*=u.x, u*u);
}



